import sys
import logging
import requests
from urllib.parse import urlparse
from xml.etree import ElementTree as ET
from datetime import datetime

def setup_logging():
    logging.basicConfig(
        filename='feed_reader.log',
        level=logging.INFO,
        format='%(asctime)s LEVEL %(levelname)s %(message)s'
    )

def fetch_url(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        return response.text
    except Exception as e:
        return None

def parse_rss(xml_content):
    try:
        root = ET.fromstring(xml_content)
        items = root.findall('.//item')
        return items
    except ET.ParseError:
        return None

def process_items(items):
    output = []
    for item in items:
        title = item.find('title')
        link = item.find('link')
        if title is not None and link is not None:
            output.append(f"{title.text}\t{link.text}")
    return output

def main():
    if len(sys.argv) != 2:
        logging.error('ERROR usage')
        sys.exit(1)

    url = sys.argv[1]
    logging.info(f'INFO start {url}')

    xml_content = fetch_url(url)
    if xml_content is None:
        logging.error('ERROR fetch')
        sys.exit(1)

    items = parse_rss(xml_content)
    if items is None:
        logging.error('ERROR parse')
        sys.exit(1)

    output_lines = process_items(items)
    logging.info(f'INFO done {len(output_lines)}')

    for line in output_lines:
        print(line)

    sys.exit(0)

if __name__ == '__main__':
    setup_logging()
    main()
